begin;
create table public.form_templates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),laboratory_id uuid not null references public.laboratories(id),code text not null,title text not null,current_version integer not null default 1,active boolean not null default true,created_at timestamptz not null default now(),unique(laboratory_id,code));
create table public.form_template_versions(id uuid primary key default gen_random_uuid(),template_id uuid not null references public.form_templates(id) on delete restrict,version_number integer not null,schema_json jsonb not null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(template_id,version_number));
create table public.form_submissions(id uuid primary key default gen_random_uuid(),template_version_id uuid not null references public.form_template_versions(id),organization_id uuid not null references public.organizations(id),laboratory_id uuid not null references public.laboratories(id),submitted_by uuid not null references public.profiles(id),payload jsonb not null,idempotency_key uuid not null unique,device_created_at timestamptz not null,server_received_at timestamptz not null default now(),sync_status text not null default 'synced');
create table public.qr_codes(id uuid primary key default gen_random_uuid(),template_id uuid not null references public.form_templates(id) on delete cascade,token_hash text not null unique,expires_at timestamptz,active boolean not null default true,created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,title text not null,body text not null,kind text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.ai_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),laboratory_id uuid not null references public.laboratories(id),document_version_id uuid references public.document_versions(id),requested_by uuid not null references public.profiles(id),model_name text not null,model_version text,prompt_version text not null,status text not null check(status in ('queued','processing','completed','failed')),created_at timestamptz not null default now(),completed_at timestamptz);
create table public.ai_findings(id uuid primary key default gen_random_uuid(),ai_review_id uuid not null references public.ai_reviews(id) on delete cascade,finding_type text not null,content text not null,confidence numeric check(confidence between 0 and 1),human_decision text check(human_decision in ('accepted','rejected')),decided_by uuid references public.profiles(id),decided_at timestamptz,check(human_decision is null or (decided_by is not null and decided_at is not null)));
create index submissions_scope_idx on public.form_submissions(organization_id,laboratory_id,server_received_at desc);
create index notifications_user_idx on public.notifications(user_id,read_at,created_at desc);
create index ai_reviews_scope_idx on public.ai_reviews(organization_id,laboratory_id,status);
alter table public.form_templates enable row level security; alter table public.form_template_versions enable row level security; alter table public.form_submissions enable row level security; alter table public.qr_codes enable row level security; alter table public.notifications enable row level security; alter table public.ai_reviews enable row level security; alter table public.ai_findings enable row level security;
create policy notifications_self on public.notifications for select to authenticated using(user_id=auth.uid());
create policy submissions_read_scope on public.form_submissions for select to authenticated using(public.is_lab_admin() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='approved' and p.laboratory_id=form_submissions.laboratory_id));
create policy submissions_insert_self on public.form_submissions for insert to authenticated with check(submitted_by=auth.uid() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='approved' and p.laboratory_id=form_submissions.laboratory_id));
commit;
